/**
* Attributes shared by events having search result data
*/
export type SearchResult = {
/** 
* Identifier used to associate search to search results across events.
*/ 
searchResultId? : string, 
/** 
* Title of the search result.
*/ 
searchResultTitle? : string, 
/** 
* Absolute position of the search result across all pages, starting at 1.
*/ 
searchResultPosition? : number, 
/** 
* Page number of the search results, starting at 1.
*/ 
searchResultPageNumber? : number, 
/** 
* Relative position of the search result on the current page, starting at 1.
*/ 
searchResultPositionInPage? : number, 
}


export function SearchResultToJSON(searchResult: SearchResult): any {
    return JSON.stringify(searchResult);
}

